mapper.select:
SELECT claim_code claimCode,subject,predicate,object_value objectValue,status,valid_from validFrom,valid_to validTo,version,confidence
FROM t_claim WHERE knowledge_base_id=#{kb} AND valid_to IS NOT NULL AND valid_to >= NOW() AND valid_to <= #{horizon}
AND (status IS NULL OR status NOT IN ('EXPIRED','SUPERSEDED','REJECTED')) ORDER BY valid_to
